; CD2481 Microcode — Decompiled Source
; Original: cd2481_ucode.bin (18432 bytes, MD5 4c487530fb0785c69b8f88df2e274762)
; Format: 8192 x 18-bit instructions, packed LE (4 per 9 bytes)
;
; Instruction format (variable, opcode determines decoding):
;   Control:  [17:13]=opcode(5b)  [12:0]=target addr(13b)
;   Data:     [17:13]=opcode(5b)  [12]=flag(1b) [11:8]=ireg(4b) [7:0]=uart_reg(8b)
;
; Known instructions:
;   JMP  0x0000 = 0x1E000  (opcode 0x0F, confirmed by datasheet)
;   CALL 0x1FFF = 0x33FFF  (opcode 0x19, 'jump 0x3FFF' in datasheet)
;
; Opcode semantics (reverse-engineered, confidence varies):
;   0x0F JMP   — unconditional jump (confirmed)
;   0x19 CALL  — call subroutine / far jump (inferred)
;   0x10 LD    — load/read UART register (inferred: partner of ST)
;   0x11 ST    — store/write UART register (inferred: TEOIR writes use this)
;   0x16 ALU   — arithmetic op, e.g. add/inc (inferred: always paired with ALU2)
;   0x1A ALU2  — logical op, e.g. and/or/sub (inferred: paired with ALU)
;   0x13 BNC   — conditional branch, main loop (inferred: first instruction)
;   0x14 BCS   — conditional branch, status check (inferred: GFRCR appears here)
;   0x15 BCFE  — conditional branch, if-else with CALL (inferred)
;   0x01 BCH   — conditional branch, channel dispatch (inferred: dispatch table)
;   0x03 BCH3  — conditional branch, channel handler entry (inferred)
;   0x04 BCC   — conditional branch, CCR-related (inferred)
;   0x00 NOP   — no-op / wait (inferred)
;
; Real code: 0x0000-0x1FCD (8142 instructions)
; Padding:  0x1FCE-0x1FFF (50 x 0x1E000)
;
; UART register map (Motorola addressing, from nm32a.c):
;   0x09 = LIVR
;   0x10 = COR1
;   0x11 = IER
;   0x13 = CCR
;   0x14 = COR5
;   0x15 = COR4
;   0x16 = COR3
;   0x17 = COR2
;   0x1A = CSR
;   0x1B = CMR
;   0x1E = SCHR2
;   0x1F = SCHR1
;   0x26 = LICR
;   0x30 = RFOC
;   0x40 = ARBADRU
;   0x42 = ARBADRL
;   0x4A = ARBCNT
;   0x4F = ARBSTS
;   0x50 = ATBADRU
;   0x52 = ATBADRL
;   0x5A = ATBCNT
;   0x5F = ATBSTS
;   0x80 = TFTC
;   0x81 = GFRCR
;   0x84 = REOIR
;   0x85 = TEOIR
;   0x86 = MEOIR
;   0x89 = RISRl
;   0x8A = TISR
;   0x8B = MISR
;   0xC0 = TCOR
;   0xC3 = TBPR
;   0xC8 = RCOR
;   0xCB = RBPR
;   0xDA = TPR
;   0xDE = MSVR_RTS
;   0xDF = MSVR_DTR
;   0xE0 = PILR2
;   0xE1 = RPILR
;   0xE3 = TPILR
;   0xE4 = MPILR
;   0xEC = TIR
;   0xED = RIR
;   0xEE = CAR
;   0xEF = MIR
;   0xF0 = AIRH
;   0xF1 = MTCR
;   0xF2 = AIRL
;   0xF3 = AIRM
;   0xF4 = BTCR_I
;   0xF6 = BTCR_M_DMR
;   0xF8 = TDR_RDR
;
; Data instruction fields:
;   flag — bit 12, meaning unknown (set in ~20% of data instructions)
;   ireg — bits [11:8], internal RISC register index (0-15)
;   uart_reg — bits [7:0], UART register address or immediate value
;
; To reassemble:  python3 cd2481_asm.py assemble <this_file> -o output.bin

